    public function navigation(array $items,string $currentSlug):array{if(current_user_can('atlas_access')){$items[]=['slug'=>'atlas-resources','label'=>__('Resources','atlas-platform'),'icon'=>'dashicons-book-alt','url'=>admin_url('admin.php?page=atlas-resources'),'capability'=>'atlas_access','current'=>$currentSlug==='atlas-resources'];}if(current_user_can('atlas_create_resources')){$items[]=['slug'=>'atlas-resource-create','label'=>__('Create Resource','atlas-platform'),'icon'=>'dashicons-edit','url'=>admin_url('admin.php?page=atlas-resource-create'),'capability'=>'atlas_create_resources','current'=>$currentSlug==='atlas-resource-create'];}if(current_user_can('atlas_review_resources')||current_user_can('atlas_publish_resources')){$items[]=['slug'=>'atlas-resource-review','label'=>__('Review Queue','atlas-platform'),'icon'=>'dashicons-yes-alt','url'=>admin_url('admin.php?page=atlas-resource-review'),'capability'=>'atlas_review_resources','current'=>$currentSlug==='atlas-resource-review'];}if(current_user_can('atlas_create_packets')){$items[]=['slug'=>'atlas-packets','label'=>__('Packets','atlas-platform'),'icon'=>'dashicons-media-document','url'=>admin_url('admin.php?page=atlas-packets'),'capability'=>'atlas_create_packets','current'=>$currentSlug==='atlas-packets'];}if(current_user_can('atlas_upload_sources')){$items[]=['slug'=>'atlas-sources','label'=>__('Sources','atlas-platform'),'icon'=>'dashicons-search','url'=>admin_url('admin.php?page=atlas-sources'),'capability'=>'atlas_upload_sources','current'=>$currentSlug==='atlas-sources'];}return$items;}
